export function effectiveCustomerId(state,rack){if(Object.hasOwn(rack,'customerId'))return rack.customerId??null;return state.shapes.find(s=>s.id===rack.sectionId)?.customerId??null;}
export function customerAssignmentConfigured(state,rack){return Object.hasOwn(rack,'customerId')||Object.hasOwn(state.shapes.find(s=>s.id===rack.sectionId)||{},'customerId');}
export function rackIsAssigned(state,rack){return customerAssignmentConfigured(state,rack)?!!effectiveCustomerId(state,rack):!!rack.assigned;}
export function customersValid(state){try{const list=state.customers??[];if(!Array.isArray(list)||list.length>500||new Set(list.map(c=>c.id)).size!==list.length||!list.every(c=>c&&typeof c.id==='string'&&c.id.length>0&&typeof c.name==='string'&&c.name.trim().length>0&&c.name.length<=100&&(c.description===undefined||typeof c.description==='string'&&c.description.length<=2000)&&(c.externalId===undefined||typeof c.externalId==='string'&&c.externalId.length<=100)))return false;const ref=o=>!Object.hasOwn(o,'customerId')||o.customerId===null||typeof o.customerId==='string'&&list.some(c=>c.id===o.customerId);const floors=Array.isArray(state.shapes)?[state]:state.floors;if(!Array.isArray(floors))return false;return floors.every(f=>Array.isArray(f.shapes)&&Array.isArray(f.racks)&&f.shapes.every(ref)&&f.racks.every(ref));}catch{return false;}}
export function removeCustomer(state,id){state.customers=state.customers.filter(c=>c.id!==id);const floors=Array.isArray(state.floors)?state.floors:[];for(const floor of [...floors,state]){for(const o of floor.shapes||[])if(o.customerId===id)o.customerId=null;for(const r of floor.racks||[])if(r.customerId===id){r.customerId=null;r.assigned=false;}}}
